SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, MIN(ss.revenue) AS min_revenue FROM store_sales ss LEFT OUTER JOIN stores s ON ss.store_id = s.id JOIN products p ON ss.product_id = p.id WHERE s.city = 'New York' GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END
